"""Embedding client for a local Ollama embedding model."""

import math
from typing import Any, Dict, List, Union

import requests

from config.settings import OLLAMA_BASE_URL, OLLAMA_EMBED_DIMENSION, OLLAMA_EMBED_MODEL


class NomicEmbedder:
    """Compatibility-named client; all embeddings are generated by Ollama."""

    def __init__(self, api_key: str = None):
        # api_key remains accepted for callers from older versions. It is never used.
        self.model = OLLAMA_EMBED_MODEL
        self.dimension = OLLAMA_EMBED_DIMENSION

    def get_embeddings(
        self, texts: List[str], task_type: str = "search_document"
    ) -> Union[List[List[float]], Dict[str, Any]]:
        if not texts:
            return []
        inputs = [f"{task_type}: {text}" for text in texts]
        try:
            response = requests.post(
                f"{OLLAMA_BASE_URL}/api/embed",
                json={"model": self.model, "input": inputs},
                timeout=(10, 180),
            )
            response.raise_for_status()
            payload = response.json()
            if not isinstance(payload, dict):
                return {"error": f"Ollama returned an invalid response for model {self.model}."}
            embeddings = payload.get("embeddings")
            if not isinstance(embeddings, list) or len(embeddings) != len(texts):
                return {"error": f"Ollama returned an unexpected embedding count for {self.model}."}
            for vector in embeddings:
                if (
                    not isinstance(vector, list)
                    or len(vector) != self.dimension
                    or any(not isinstance(value, (int, float)) or not math.isfinite(value) for value in vector)
                ):
                    actual = len(vector) if isinstance(vector, list) else "invalid"
                    return {
                        "error": (
                            f"Ollama model {self.model} returned a vector with dimension {actual}; "
                            f"configured dimension is {self.dimension}. Set OLLAMA_EMBED_DIMENSION "
                            "to the model's actual dimension and use a separate vector collection."
                        )
                    }
            return embeddings
        except requests.Timeout:
            return {"error": f"Ollama embedding timed out at {OLLAMA_BASE_URL}. Check that the model is available and responsive."}
        except requests.ConnectionError:
            return {
                "error": (
                    f"Cannot connect to Ollama at {OLLAMA_BASE_URL}. Start Ollama and run "
                    f"`ollama pull {self.model}`, then retry."
                )
            }
        except requests.RequestException as exc:
            error_response = getattr(exc, "response", None)
            if getattr(error_response, "status_code", None) == 404:
                return {
                    "error": (
                        f"Ollama model {self.model} is not available. Run `ollama pull {self.model}` "
                        f"and verify OLLAMA_BASE_URL={OLLAMA_BASE_URL}."
                    )
                }
            detail = getattr(error_response, "text", "")
            return {"error": f"Ollama could not generate embeddings with model {self.model}: {detail or exc}"}
        except (ValueError, TypeError) as exc:
            return {"error": f"Ollama returned an invalid embedding response: {exc}"}
